#![no_std]

pub fn locate_binary(haystack: &[u8]) -> Option<usize> {
    zscan::find(haystack, b"\0\xff")
}

#[cfg(test)]
mod tests {
    #[test]
    fn registry_package_exports_and_binary_semantics() {
        let h = b"a\0\xffa\0\xff";
        assert_eq!(super::locate_binary(h), Some(1));
        assert_eq!(zscan::rfind(h, b"\0\xff"), Some(4));
        assert_eq!(zscan::find_byte(255, h), Some(2));
        assert_eq!(zscan::rfind_byte(255, h), Some(5));
        let finder = zscan::Finder::new(b"\0\xff");
        assert_eq!(finder.find(h), Some(1));
        assert_eq!(finder.rfind(h), Some(4));
        assert_eq!(zscan::find(h, b""), Some(0));
        assert_eq!(zscan::rfind(h, b""), Some(h.len()));
        assert_eq!(zscan::find(h, b"longer than the haystack"), None);
    }
}
